namespace OpenScctEditor.Shell;

public static partial class TutorialCatalog
{
    private static IEnumerable<EditorTutorial> AnimationLessons() =>
    [
        new("animation-start", "Animation: your first keyframes", "animation studio example beginner bone pose move rotate scale keyframe scrub timeline", [
            S("Start with the example", "Animation Studio is open on Stock. Click Create example rig for a small three-bone Wave animation that needs no game content. Save any existing animation project when prompted. Tutorials never replace your project for you.", "animation:Stock|Create example rig"),
            S("Choose a bone", "In the right-hand hierarchy select Upper or Hand. The stage marks the selected bone with a bright circle and coloured handles. Clicking a bone dot in the stage selects the same hierarchy entry.", "animation:RigHierarchy"),
            S("Choose the editing tool", "Click Rotate to show three coloured rotation rings. Drag a ring to turn the selected bone. Move shows arrow handles; Scale shows square handles. Red is X, green is Y and blue is Z. Hold Shift while dragging to snap.", "animation:AnimationTool_rotate"),
            S("Scrub before playing", "Drag the slider beneath the stage to a different time. You can scrub immediately without pressing Play. The time label and yellow timeline playhead show the current sample. Choose a time away from zero for your second pose.", "animation:AnimationSeek"),
            S("Record and preview", "With Auto key enabled, releasing a pose handle records keys at the playhead. With it off, use Key pose after editing. Press Play or Space to preview, then pause and scrub to compare poses. Ctrl+Z undoes the last recorded edit.", "animation:Key pose"),
            S("Save the animation project", "Click Save to choose an .osanim project folder. This saves the editable rig, clips and keys separately from your map. Save As makes a portable copy. Reopen the project later to continue editing.", "animation:Save")]),
        new("animation-stock", "Animation: edit a Spy or Merc clip", "animation import stock character library spy merc clip duplicate hierarchy pose", [
            S("Import a character", "Use Import Spy rig or Import Merc rig in Stock. Installed OpenSCCT character content is required. Each import adds an editable model, skeleton and its animation clips to this project. The stage frames the character above its reference floor.", "animation:Stock|Import Spy rig"),
            S("Choose a motion", "Switch to Project and click a clip in the left-hand list. Scrub its motion before editing. Different clips have different durations; the seek slider follows the selected clip's full duration.", "animation:Project|AnimationClips"),
            S("Make a working copy", "Use the copy icon beside + Clip to duplicate the selected motion. Use the Clip inspector to rename it. This gives your edited motion its own clip while retaining the imported one for comparison.", "animation:Project|AnimationDuplicateClip"),
            S("Pose at the playhead", "Select a bone in the hierarchy, choose Move, Rotate or Scale, and drag a coloured handle. The Pose inspector also accepts precise position, rotation and scale values. World switches the editing axes into world space.", "animation:Pose|RigHierarchy"),
            S("Preview the result", "Use Frame to fit the rigs in the stage. Middle-drag orbits, Shift+middle pans and the wheel zooms. Play and scrub through the edited clip, checking hands, feet and the transition around the loop, then Save.", "animation:Frame")]),
        new("animation-scene", "Animation: manage scene items", "animation studio scene rig add remove delete duplicate actor model item paired interaction undo", [
            S("Open scene items", "Scene items opens the Scene inspector. It lists each rig instance in this animation project. Imported clips and skeletons are assets; a scene rig is one instance using those assets.", "animation:Scene items"),
            S("Select the instance", "Click Select rig beside the item you want to pose. Its assigned clip becomes active and the hierarchy follows its skeleton. Start offset and Position X/Y/Z arrange the scene without changing the model asset.", "animation:Scene|Select rig"),
            S("Add another instance", "Duplicate rig makes an independently positioned copy. Add rig places the selected skeleton and clip back into the scene. When instances share a clip, editing that clip affects both; duplicate the clip for different motions.", "animation:Scene|Add rig"),
            S("Remove an item", "Click Remove rig beside the unwanted item. Its scene instance and dependent scene links are removed; the imported clips and model remain available. Ctrl+Z restores the removal, including its links. Removing the last rig leaves an empty stage.", "animation:Scene|Remove rig"),
            S("Begin a separate project", "Save first, then click New for a separate animation project. Choose whether to save or discard when prompted. The old models, bone dots and transform handles disappear together; the new project starts empty.", "animation:New")]),
        new("animation-replacements", "Animation: test replacements in game", "animation bindings replacement play practice testrange export test openscct", [
            S("Choose the edited clip", "Import a stock Spy or Merc and select the motion you edited. Save the project. Test in OpenSCCT previews project clips in an isolated model viewer; Play replacements tests explicit slot bindings during normal character actions.", "animation:Project|AnimationClips"),
            S("Bind the correct slot", "In Bindings enter the target mesh, for example SPerso.ATT_01, and the existing animation slot you want to replace. Start with the imported clip's original name. Leave Visual selected to preserve gameplay timing, then click Bind selected clip.", "animation:Bindings|Bind selected clip"),
            S("Launch the practice room", "Click Play replacements. The editor builds a private practice room and animation overlay, so this works with an installed game that has no development TestRange map. Stock character content and an Animation Studio compatible OpenSCCT installation are still required.", "animation:Play replacements"),
            S("Trigger and compare", "In the game, perform the action that uses the bound slot. A binding only replaces an existing action; it does not add a new action. Return to the editor, adjust keys and launch again to rebuild the private overlay.", "animation:AnimationStage"),
            S("Keep a portable result", "Save your .osanim project for future edits. Export an .osanimpack for the compiled animation content or GLB/glTF for interchange. Add to Map copies animation assets into your open map project; save and build that map separately.", "animation:Export…")]),
        new("animation-first-person", "Animation: first-person weapon and arms", "animation first person spy merc weapon arms eye view action reload fire bind", [
            S("Open First Person", "Use the section selector beneath the file buttons to choose First Person. Select Spy or Merc and the desired weapon. This navigates to the authoring controls without replacing or importing anything until you choose Load setup.", "animation:AnimationStudioSection"),
            S("Load the real setup", "Click Load setup to import the role's first-person assets from installed OpenSCCT content. The Spy setup includes weapon and arms. Choose an Action such as Idle or Fire, then use Edit to switch between Weapon and Arms.", "animation:Load setup"),
            S("Create an action copy", "New action clip duplicates the selected motion into this setup's selected action. Select a bone, scrub to the desired time and record pose edits with Auto key or Key pose. Review the weapon and arms together.", "animation:New action clip"),
            S("Check the framing", "Eye view uses the game's first-person camera framing; Orbit lets you inspect the assembly from outside. Adjust FOV and check that the weapon, hands and action remain readable throughout the clip.", "animation:Eye view"),
            S("Enable and test", "Bind actions enables explicit visual replacements for the setup's slots. Use Play replacements to test supported actions in the practice room. Editing an unused slot does not create a new in-game action. Save the editable project afterwards.", "animation:Bind actions")]),
    ];
}
